quota_scripts.script:
function httpErr(e) {
  var m = e && e.message ? String(e.message) : String(e);
  if (m.indexOf("HTTP ") === 0) return m;
  if (m.indexOf("JSON parse: ") === 0) return "Parse: " + m.slice(12);
  return "Network: " + m;
}
function intVal(v) {
  return typeof v === "number" && Number.isInteger(v) ? v : null;
}
function msToIso(ms) {
  try {
    var iso = new Date(ms).toISOString();
  } catch (e) {
    return null;
  }
  if (ms % 1000 === 0) return iso.slice(0, 19) + "+00:00";
  return iso.slice(0, 23) + "+00:00";
}
function numField(obj, f, d) {
  if (obj == null) return d;
  var v = obj[f];
  if (typeof v === "number") return v;
  if (typeof v === "string" && v.trim() !== "" && !isNaN(Number(v))) return Number(v);
  return d;
}
function tier(name, src) {
  if (src == null || typeof src !== "object" || Array.isArray(src)) src = {};
  var limit = numField(src, "limit", 1.0);
  var remaining = numField(src, "remaining", 0.0);
  var used = Math.max(limit - remaining, 0.0);
  var utilization = limit > 0.0 ? (used / limit) * 100.0 : 0.0;
  var rt = src.resetTime;
  var resets_at = typeof rt === "string" ? rt : (intVal(rt) === null ? null : msToIso(intVal(rt)));
  return { name: name, utilization: utilization, resets_at: resets_at, limit: limit, remaining: remaining };
}
var body;
try {
  body = http.get("https://api.kimi.com/coding/v1/usages", { "Authorization": "Bearer " + ctx.apiKey });
} catch (e) {
  return { success: false, error: httpErr(e) };
}
if (body == null || typeof body !== "object" || Array.isArray(body)) body = {};
var tiers = [];
if (Array.isArray(body.limits)) {
  for (var i = 0; i < body.limits.length; i++) {
    var item = body.limits[i];
    if (item == null) continue;
    if (item.detail === undefined) continue;
    tiers.push(tier("five_hour", item.detail));
  }
}
if (body.usage !== undefined) {
  tiers.push(tier("weekly_limit", body.usage));
}
return {
  success: true,
  error: null,
  balance: null,
  coding_plan: { level: null, tiers: tiers }
};
